using namespace rendering;
namespace {
unsigned checks=0;
void Check(bool b,const char* text){++checks;if(!b)throw std::runtime_error(text);}
template<class F>void Reject(F&& f,const char* text){bool bad=false;try{f();}catch(const std::exception&){bad=true;}Check(bad,text);}
std::shared_ptr<const NativeMetalDensity> Density(uint8_t offset=0){auto d=std::make_shared<NativeMetalDensity>();d->width=3;d->height=2;d->values={uint8_t(0+offset),uint8_t(50+offset),uint8_t(100+offset),uint8_t(150+offset),uint8_t(200+offset),uint8_t(250+offset)};return d;}
std::shared_ptr<const NativeMetalExtraction> Extraction(float depth,bool global=false){auto e=std::make_shared<NativeMetalExtraction>();e->width=3;e->height=2;e->losWidth=2;e->losHeight=1;e->depth.assign(6,depth);e->los={0,7};e->globalLos=global;return e;}
}
int main(){try{
 SetNativeMetalInfoGPUReady(false);SetNativeMetalInfoMaintenanceReady(false);Check(!IsNativeMetalInfoConsumerAvailable(),"No fabricated metal producer");SetNativeMetalInfoGPUReady(true);Check(!IsNativeMetalInfoConsumerAvailable(),"PSO alone does not advertise connected mode");SetNativeMetalInfoMaintenanceReady(true);Check(IsNativeMetalInfoConsumerAvailable(),"Both actual layers needed");SetNativeMetalInfoGPUReady(false);Check(!IsNativeMetalInfoConsumerAvailable(),"Revoking GPU removes capability");SetNativeMetalInfoMaintenanceReady(false);
 NativeMetalInfoRecorder recorder;const auto initial=recorder.Capture();Check(initial->mapIdentity&&!initial->active,"Original map lifetime starts inactive");recorder.SetMode(true,1,6,4,8,4);auto selected=recorder.Capture();Check(selected->active&&selected->updates.size()==1&&selected->updates[0].clear&&selected->updates[0].repetitions==0,"Original immediate black clear, no invented blend");ValidateNativeMetalInfoFrame(*selected);
 auto a=Density(),b=Density(1);auto e1=Extraction(.0005f),e2=Extraction(.001f),e3=Extraction(-.0001f,true);
 Check(recorder.NeedsExtractionUpdate(),"Original forced first extraction");recorder.Update(a,e1);auto first=recorder.Capture();Check(first->updates.size()==2&&first->updates.back().extraction==e1,"Initialize actual auxiliary inputs before first defined sample");Check(recorder.NeedsExtractionUpdate(),"Original short-circuited firstUpdate leaves updateN0");recorder.Update(b,e2);auto second=recorder.Capture();Check(second->updates.back().extraction==e1&&second->updates.back().density==a,"Original combiner precedes this tick auxiliary updates");Check(!recorder.NeedsExtractionUpdate(),"Second tick advances original modulo counter");
 recorder.Update(b,{});auto third=recorder.Capture();Check(third->updates.back().extraction==e2&&third->updates.back().density==b,"Next tick consumes the newly updated extraction/density");Check(first->updates.back().extraction==e1&&first->updates.back().density==a,"Recorded old sources remain immutable owners");
 unsigned updates=2;for(unsigned tick=4;tick<=62;++tick){const bool need=recorder.NeedsExtractionUpdate();if(need){++updates;Check(tick==32||tick==62,"Exact original extraction update cadence");}recorder.Update(b,need?e3:nullptr);}
 Check(updates==4,"Original initial2 + tick32 + tick62, no render-driven changes");auto repeat=recorder.Capture();Check(repeat->updates.back().repetitions>1,"Identical repeated original blends retained as exact count");uint64_t draws=0;for(const auto&u:repeat->updates){if(!u.clear)draws+=u.repetitions;}Check(draws==62,"No temporal updates dropped or merged into an approximate color");Check(repeat->updates.back().extraction==e3,"Live later snapshot owns updated extraction-time LOS/global flag");
 Reject([&]{recorder.Retire(repeat->serial-1);},"Cannot falsely acknowledge partial GPU completion");Check(recorder.Capture()->updates.size()==repeat->updates.size(),"Rejected completion preserves pending work");recorder.Retire(repeat->serial);Check(recorder.Capture()->updates.empty(),"Actual whole transaction completion retires source queue");Check(repeat->updates.size()>1,"Already captured immutable queue survives retirement");
 auto prior=recorder.Capture();Reject([&]{auto candidate=recorder;candidate.SetMode(true,std::numeric_limits<float>::quiet_NaN(),6,4,8,4);},"Reject nonfinite brightness before mode mutation");Check(recorder.Capture()->modeGeneration==prior->modeGeneration,"Failed mode transaction preserves current mode");
 NativeMetalInfoRecorder invalid=recorder;auto bad=std::make_shared<NativeMetalDensity>(*b);bad->values.pop_back();Reject([&]{invalid.Update(bad,nullptr);},"Reject incomplete density map before any update");Check(invalid.Capture()->serial==prior->serial,"Invalid data cannot partially advance serial");auto invalidExtraction=std::make_shared<NativeMetalExtraction>(*e1);invalidExtraction->depth[1]=std::numeric_limits<float>::infinity();Reject([&]{ValidateNativeMetalExtraction(*invalidExtraction);},"Reject nonfinite raw extraction");ValidateNativeMetalExtraction(*e3);Check(e3->depth[0]<0,"Preserve original finite signed extraction values");
 auto malformed=*repeat;malformed.updates.back().lastSerial=malformed.serial+1;Reject([&]{ValidateNativeMetalInfoFrame(malformed);},"Reject out-of-range queued serial");malformed=*repeat;malformed.updates.back().repetitions=0;Reject([&]{ValidateNativeMetalInfoFrame(malformed);},"Reject lost repetition count");
 malformed=*repeat;malformed.serial++;Reject([&]{ValidateNativeMetalInfoFrame(malformed);},"Reject an omitted trailing update instead of falsely retiring it");malformed=*repeat;malformed.updates.back().firstSerial++;malformed.updates.back().repetitions--;Reject([&]{ValidateNativeMetalInfoFrame(malformed);},"Reject a gap between queued original update intervals");
 recorder.SetMode(false,1,6,4,8,4);auto disabled=recorder.Capture();Check(!disabled->active&&disabled->updates.empty(),"Original non-metal mode leaves no pending metal writes");recorder.SetMode(true,2,6,4,8,4);auto changed=recorder.Capture();Check(changed->modeGeneration>selected->modeGeneration&&changed->updates[0].clear&&changed->updates[0].brightness==2,"Same-mode reload clears black and freezes current shader brightness");
 const auto identity=changed->mapIdentity;recorder.Reset();Check(recorder.Capture()->mapIdentity!=identity&&!recorder.Capture()->active&&recorder.NeedsExtractionUpdate(),"Map reload cannot reuse old GPU history/identity/cadence");std::cout<<"PASS "<<checks<<" native metal source/cadence/immutable transaction checks\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
